sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    if (newValue.toString().indexOf('none') !== -1) {
        if (g_form.getValue('data_classification_of_affected_assets') === 'none') {
            return; // already set correctly, don't fire again
        }
        g_form.clearValue('data_classification_of_affected_assets');
        g_form.setValue('data_classification_of_affected_assets', 'none');
        g_form.addInfoMessage('None Identified clears all other data classifications — other values have been removed.');
    }

}
